#include "velox/expression/Expr.h"

namespace facebook::velox::exec {

class SpecialForm : public Expr {
 public:
  SpecialForm(
      TypePtr type,
      std::vector<ExprPtr> inputs,
      const std::string& name,
      bool supportsFlatNoNullsFastPath,
      bool trackCpuUsage)
      : Expr(
            std::move(type),
            std::move(inputs),
            name,
            true /* specialForm */,
            supportsFlatNoNullsFastPath,
            trackCpuUsage) {}
};
